import Foundation
import CryptoKit
public enum ManifestFailure:Error,Equatable{case unsupported,invalid,sourceChanged,authorization,storage,stale,partial,waitingForResource,fidelityPending}
public enum ManifestState:String,Codable,Sendable{case discovered="DISCOVERED",capturing="CAPTURING",partial="PARTIAL",completeLocal="COMPLETE_LOCAL",backingUp="BACKING_UP",partiallyProtected="PARTIALLY_PROTECTED",fullyProtected="FULLY_PROTECTED",restoreReady="RESTORE_READY",incomplete="INCOMPLETE",sourceChanged="SOURCE_CHANGED",unsupported="UNSUPPORTED",error="ERROR"}
public enum MediaKind:String,Codable,Sendable{case ordinary="ORDINARY",livePhoto="LIVE_PHOTO",raw="RAW",rawJPEG="RAW_JPEG",edited="EDITED",complex="COMPLEX",legacy="LEGACY_SINGLE"}
public enum ResourceRole:String,Codable,Sendable{case still="PRIMARY_STILL",video="PRIMARY_VIDEO",pairedVideo="PAIRED_VIDEO",raw="RAW_ORIGINAL",jpeg="JPEG_COMPANION",edited="EDITED_RENDER",adjustment="ADJUSTMENT_DATA",adjustmentBase="ADJUSTMENT_BASE",depth="DEPTH_DATA",auxiliary="AUXILIARY",unknownRequired="UNKNOWN_REQUIRED",unknownOptional="UNKNOWN_OPTIONAL",preview="DERIVED_PREVIEW"}
public enum ResourceClass:String,Codable,Sendable{case original="ORIGINAL",edited="EDITED",auxiliary="AUXILIARY",derived="DERIVED",unknown="UNKNOWN"}
public struct ManifestBinding:Codable,Equatable,Sendable{public let accountID:UUID,deviceID:UUID,libraryID:UUID;public init(accountID:UUID,deviceID:UUID,libraryID:UUID){self.accountID=accountID;self.deviceID=deviceID;self.libraryID=libraryID}}
public struct ResourceDescriptor:Codable,Equatable,Sendable{
 public let ordinal:Int,resourceType:Int,uti:String,role:ResourceRole,resourceClass:ResourceClass,required:Bool
 public init(ordinal:Int,resourceType:Int,uti:String){self.ordinal=ordinal;self.resourceType=resourceType;self.uti=uti;let raw=uti.lowercased().contains("raw")||uti.lowercased().contains("dng");switch resourceType{case 1:role=raw ? .raw:.still;resourceClass = .original;required=true;case 2:role = .video;resourceClass = .original;required=true;case 4:role=raw ? .raw:.jpeg;resourceClass = .original;required=true;case 9:role = .pairedVideo;resourceClass = .original;required=true;case 5,6,10:role = .edited;resourceClass = .edited;required=true;case 7:role = .adjustment;resourceClass = .auxiliary;required=true;case 8,11,12:role = .adjustmentBase;resourceClass = .auxiliary;required=true;case 19:role = .preview;resourceClass = .derived;required=false;default:role = .unknownRequired;resourceClass = .unknown;required=true}}
 public var safe:Bool{ordinal>=0&&ordinal<16&&resourceType>0&&resourceType<=65535&&uti.range(of:"^[-a-zA-Z0-9.]{1,128}$",options:.regularExpression) != nil}
}
public struct MediaSourceSnapshot:Codable,Equatable,Sendable{
 public let localID:String,mediaType:String,livePhoto:Bool,width:Int,height:Int,creation:Date?,modification:Date?,duration:Double?,resources:[ResourceDescriptor]
 public init(localID:String,mediaType:String,livePhoto:Bool=false,width:Int=1,height:Int=1,creation:Date?=nil,modification:Date?=nil,duration:Double?=nil,resources:[ResourceDescriptor]){self.localID=localID;self.mediaType=mediaType;self.livePhoto=livePhoto;self.width=width;self.height=height;self.creation=creation;self.modification=modification;self.duration=duration;self.resources=resources}
 public var fingerprint:String{let encoder=JSONEncoder();encoder.outputFormatting=[.sortedKeys];return SHA256.hash(data:(try? encoder.encode(self)) ?? Data()).map{String(format:"%02x",$0)}.joined()}
 public var enumerationValid:Bool{!resources.isEmpty&&resources.count<=16&&resources.allSatisfy(\.safe)&&Set(resources.map(\.ordinal)).count==resources.count&&localID.utf8.count<=1024&&["image","video"].contains(mediaType)&&width>0&&height>0}
 public var kind:MediaKind{if resources.contains(where:{$0.resourceClass == .unknown}) && !livePhoto{return .complex};if livePhoto{return .livePhoto};if resources.contains(where:{$0.role == .edited||$0.role == .adjustment}){return .edited};if resources.contains(where:{$0.role == .raw}){return resources.contains(where:{$0.role == .still||$0.role == .jpeg}) ? .rawJPEG:.raw};return resources.filter(\.required).count==1 ? .ordinary:.complex}
 public var shapeComplete:Bool{guard resources.contains(where:{$0.required && $0.resourceClass == .original}),!resources.isEmpty,resources.count<=16,resources.allSatisfy(\.safe),Set(resources.map(\.ordinal)).count==resources.count,!resources.contains(where:{$0.resourceClass == .unknown}),["image","video"].contains(mediaType),width>0,height>0 else{return false};let roles=resources.map(\.role);switch kind{case .livePhoto:return roles.filter{$0 == .still}.count==1&&roles.filter{$0 == .pairedVideo}.count==1;case .rawJPEG:return roles.contains(.raw)&&(roles.contains(.still)||roles.contains(.jpeg));case .edited:return roles.contains(.edited)&&roles.contains(.adjustment)&&resources.contains{$0.resourceClass == .original};case .ordinary:return roles.contains(mediaType=="video" ? .video:.still);default:return true}}
}
public struct ManifestResource:Codable,Equatable,Identifiable,Sendable{
 public let id:UUID,descriptor:ResourceDescriptor
 public var expectedSize:Int?,expectedSha256:String?,serverAssetID:UUID?,protectedVersionID:String?,status:String="NOT_CAPTURED",waitingForNetwork=false
 public init(id:UUID=UUID(),descriptor:ResourceDescriptor){self.id=id;self.descriptor=descriptor}
 public var captured:Bool{guard let size=expectedSize,let sha=expectedSha256 else{return false};return size>0&&size<=10*1024*1024*1024&&sha.range(of:"^[a-f0-9]{64}$",options:.regularExpression) != nil}
}
public struct MediaManifest:Codable,Equatable,Identifiable,Sendable{
 // Protected cloud versions are immutable; only unfinished captures follow the device source.
 public var requiresSourceRevalidation:Bool{![ManifestState.fullyProtected,.restoreReady].contains(state)}

 public let id:UUID,manifestVersion:Int,binding:ManifestBinding,sourceToken:UUID,source:MediaSourceSnapshot,createdAt:Date
 public var resources:[ManifestResource],state:ManifestState = .discovered,revision=0,updatedAt=Date(),serverFingerprint:String?,changedFingerprint:String?
 public init(id:UUID=UUID(),binding:ManifestBinding,sourceToken:UUID=UUID(),source:MediaSourceSnapshot,manifestVersion:Int=1){self.id=id;self.manifestVersion=manifestVersion;self.binding=binding;self.sourceToken=sourceToken;self.source=source;createdAt=Date();resources=source.resources.map{ManifestResource(descriptor:$0)};if !source.shapeComplete{state = .unsupported}}
 public var required:[ManifestResource]{resources.filter{$0.descriptor.required}}
 public var completeLocal:Bool{manifestVersion==1&&source.shapeComplete&&required.allSatisfy(\.captured) && !required.isEmpty}
 public func matchesResource(_ r:ManifestResource,_ p:ServerManifestResource)->Bool{let role=r.descriptor.role == .still && source.kind == .rawJPEG ? ResourceRole.jpeg:r.descriptor.role;return p.id==r.id && p.role==role && p.resourceType==r.descriptor.resourceType && p.uti==r.descriptor.uti && p.required==r.descriptor.required && p.resourceClass==r.descriptor.resourceClass && p.expectedSize==r.expectedSize && p.expectedSha256==r.expectedSha256}
 public var protectedBytes:Int64{resources.filter{$0.status=="PROTECTED"}.reduce(0){$0+Int64($1.expectedSize ?? 0)}}
 public func matches(_ fresh:MediaSourceSnapshot)->Bool{source==fresh&&source.fingerprint==fresh.fingerprint}
 public func wireMetadata()throws->[String:Any]{guard manifestVersion==1,source.enumerationValid else{throw ManifestFailure.unsupported};let formatter=ISO8601DateFormatter();return["id":id.uuidString.lowercased(),"deviceId":binding.deviceID.uuidString.lowercased(),"libraryId":binding.libraryID.uuidString.lowercased(),"sourceToken":sourceToken.uuidString.lowercased(),"sourceFingerprint":source.fingerprint,"manifestVersion":1,"mediaType":source.mediaType,"kind":source.kind.rawValue,"policy":"PRESERVE_ALL_AVAILABLE","creationTime":source.creation.map{formatter.string(from:$0)} as Any? ?? NSNull(),"modificationTime":source.modification.map{formatter.string(from:$0)} as Any? ?? NSNull(),"pixelWidth":source.width,"pixelHeight":source.height,"durationSeconds":source.duration as Any? ?? NSNull(),"resources":resources.map{["id":$0.id.uuidString.lowercased(),"role":($0.descriptor.role == .still&&source.kind == .rawJPEG ? ResourceRole.jpeg:$0.descriptor.role).rawValue,"resourceType":$0.descriptor.resourceType,"uti":$0.descriptor.uti]}]}
}
public struct ManifestResourceBinding:Codable,Equatable,Sendable{
 public let manifestID:UUID,resourceID:UUID,sourceLocalID:String,sourceFingerprint:String,descriptor:ResourceDescriptor,binding:ManifestBinding
 public init(manifest:MediaManifest,resource:ManifestResource){manifestID=manifest.id;resourceID=resource.id;sourceLocalID=manifest.source.localID;sourceFingerprint=manifest.source.fingerprint;descriptor=resource.descriptor;binding=manifest.binding}
}
public struct ServerManifestResource:Codable,Equatable,Sendable{public let id:UUID,role:ResourceRole,resourceType:Int,uti:String,required:Bool,resourceClass:ResourceClass,expectedSize:Int?,expectedSha256:String?,assetId:UUID?,cloudVersionId:String?,status:String}
public struct ServerManifestProof:Codable,Equatable,Sendable{public let id:UUID,manifestVersion:Int,kind:MediaKind,mediaType:String,policy:String,legacy:Bool,protection:String,requiredCount:Int,protectedCount:Int,sourceFingerprint:String,sourceChanged:Bool,reviewRequired:Bool,integrityDegraded:Bool,manifestFingerprint:String,resources:[ServerManifestResource]}
public enum MediaCleanupEligibility{
 public static func eligible(_ manifest:MediaManifest,proof:ServerManifestProof,fresh:MediaSourceSnapshot,binding:ManifestBinding,fidelityAccepted:Bool)->Bool{guard fidelityAccepted,manifest.binding==binding,manifest.matches(fresh),fresh.modification != nil,manifest.manifestVersion==1,proof.manifestVersion==1,manifest.id==proof.id,manifest.source.fingerprint==proof.sourceFingerprint,manifest.source.shapeComplete,proof.protection=="FULLY_PROTECTED",!proof.sourceChanged,!proof.reviewRequired,!proof.integrityDegraded,proof.requiredCount==manifest.required.count,proof.protectedCount==proof.requiredCount else{return false};return manifest.required.allSatisfy{r in proof.resources.contains{$0.id==r.id&&manifest.matchesResource(r,$0)&&$0.cloudVersionId?.range(of:"^[a-f0-9]{64}$",options:.regularExpression) != nil&&$0.assetId != nil&&$0.status=="PROTECTED"&&$0.required}}
 }
}
